package com.mlserver.inference;

import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.GCMParameterSpec;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import com.sun.net.httpserver.*;

public class ModelInferenceServer {
    private static final String MODEL_VAULT = "/opt/mlserver/models/";
    private static final String MANIFEST_DIR = "/opt/mlserver/manifests/";
    // Key must be provided via secure external configuration, never hardcoded.
    private static final byte[] AES_KEY = loadAesKey();
    private static final int GCM_IV_LENGTH = 12;
    private static final int GCM_TAG_BITS = 128;
    private static final ConcurrentHashMap<String, byte[]> modelCache = new ConcurrentHashMap<>();

    private static byte[] loadAesKey() {
        String keyB64 = System.getenv("MLSERVER_AES_KEY");
        if (keyB64 == null || keyB64.isEmpty()) {
            throw new IllegalStateException("MLSERVER_AES_KEY environment variable is not set");
        }
        byte[] key = Base64.getDecoder().decode(keyB64);
        if (key.length != 16 && key.length != 24 && key.length != 32) {
            throw new IllegalStateException("MLSERVER_AES_KEY must decode to a 128/192/256-bit key");
        }
        return key;
    }

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new java.net.InetSocketAddress(8080), 0);
        server.createContext("/api/v1/inference", new InferenceHandler());
        server.createContext("/api/v1/models", new ModelLoadHandler());
        server.start();
    }

    static class ModelLoadHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0);
                exchange.close();
                return;
            }
            String body = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
            Map<String, String> params = parseJson(body);
            String modelId = params.get("model_id");
            String version = params.get("version");

            try {
                byte[] modelData = loadEncryptedModel(modelId, version);
                modelCache.put(modelId + ":" + version, modelData);
                String resp = "{\"status\":\"loaded\",\"model_id\":\"" + modelId + "\"}";
                exchange.sendResponseHeaders(200, resp.length());
                exchange.getResponseBody().write(resp.getBytes());
            } catch (Exception e) {
                String resp = "{\"error\":\"" + e.getMessage() + "\"}";
                exchange.sendResponseHeaders(500, resp.length());
                exchange.getResponseBody().write(resp.getBytes());
            }
            exchange.close();
        }
    }

    static class InferenceHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0);
                exchange.close();
                return;
            }
            String body = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
            Map<String, String> params = parseJson(body);
            String modelId = params.get("model_id");
            String version = params.getOrDefault("version", "latest");
            String key = modelId + ":" + version;

            if (!modelCache.containsKey(key)) {
                String resp = "{\"error\":\"model not loaded\"}";
                exchange.sendResponseHeaders(404, resp.length());
                exchange.getResponseBody().write(resp.getBytes());
                exchange.close();
                return;
            }
            String resp = "{\"prediction\":[0.85,0.12,0.03],\"model\":\"" + modelId + "\"}";
            exchange.sendResponseHeaders(200, resp.length());
            exchange.getResponseBody().write(resp.getBytes());
            exchange.close();
        }
    }

    private static byte[] loadEncryptedModel(String modelId, String version) throws Exception {
        String manifestPath = resolveManifestPath(modelId);
        String manifest = new String(Files.readAllBytes(Paths.get(manifestPath)), StandardCharsets.UTF_8);
        Map<String, String> manifestData = parseJson(manifest);

        String encryptedRelPath = manifestData.get("encrypted_path");
        String checksum = manifestData.get("checksum");

        Path modelPath = resolveModelArtifact(modelId, version, encryptedRelPath);
        byte[] encryptedData = Files.readAllBytes(modelPath);
        byte[] decryptedData = decryptAES(encryptedData);

        if (!verifyChecksum(decryptedData, checksum)) {
            throw new SecurityException("Model checksum verification failed");
        }
        return decryptedData;
    }

    private static String resolveManifestPath(String modelId) {
        // Sanitize modelId: only allow alphanumeric and hyphens
        String sanitized = modelId.replaceAll("[^a-zA-Z0-9\\-]", "");
        return MANIFEST_DIR + sanitized + ".json";
    }

    private static Path resolveModelArtifact(String modelId, String version, String encryptedRelPath) throws SecurityException {
        // Build the artifact path from manifest-provided relative path
        // The manifest is trusted (from our own manifest directory), so we use its path directly
        String basePath = MODEL_VAULT + modelId + "/" + version + "/";
        Path resolved = Paths.get(basePath).resolve(encryptedRelPath).normalize();

        // Security check: ensure resolved path starts with MODEL_VAULT
        String resolvedStr = resolved.toString();
        if (!resolvedStr.startsWith(MODEL_VAULT)) {
            throw new SecurityException("Path traversal detected: resolved path outside model vault");
        }
        return resolved;
    }

    private static byte[] decryptAES(byte[] data) throws Exception {
        if (data.length < GCM_IV_LENGTH + (GCM_TAG_BITS / 8)) {
            throw new IllegalArgumentException("Invalid encrypted data");
        }
        byte[] iv = Arrays.copyOfRange(data, 0, GCM_IV_LENGTH);
        byte[] ciphertext = Arrays.copyOfRange(data, GCM_IV_LENGTH, data.length);
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(AES_KEY, "AES"), new GCMParameterSpec(GCM_TAG_BITS, iv));
        return cipher.doFinal(ciphertext);
    }

    private static boolean verifyChecksum(byte[] data, String expected) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] hash = md.digest(data);
        byte[] expectedBytes = hexToBytes(expected);
        // Constant-time comparison to avoid timing side-channels.
        return MessageDigest.isEqual(hash, expectedBytes);
    }

    private static byte[] hexToBytes(String hex) {
        if (hex == null || (hex.length() % 2) != 0) {
            return new byte[0];
        }
        int len = hex.length();
        byte[] out = new byte[len / 2];
        try {
            for (int i = 0; i < len; i += 2) {
                out[i / 2] = (byte) ((Character.digit(hex.charAt(i), 16) << 4)
                        + Character.digit(hex.charAt(i + 1), 16));
            }
        } catch (Exception e) {
            return new byte[0];
        }
        return out;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) sb.append(String.format("%02x", b));
        return sb.toString();
    }

    private static Map<String, String> parseJson(String json) {
        Map<String, String> map = new HashMap<>();
        json = json.trim();
        if (json.startsWith("{") && json.endsWith("}")) {
            json = json.substring(1, json.length() - 1);
            String[] pairs = json.split(",");
            for (String pair : pairs) {
                String[] kv = pair.split(":", 2);
                if (kv.length == 2) {
                    String key = kv[0].trim().replaceAll("\"", "");
                    String value = kv[1].trim().replaceAll("\"", "");
                    map.put(key, value);
                }
            }
        }
        return map;
    }
}
